-- Schema evolution with ALTER TABLE (applied after 01_schema.sql, safe to re-run on an existing DB)

-- Human-readable "feel" description generated by the ETL from audio features
-- (e.g. "slow, acoustic, melancholic. Good for: a rainy evening"). It is also part of the embedded text.
ALTER TABLE songs ADD COLUMN IF NOT EXISTS description TEXT;

-- Richer taste profile used by recommend():
--   taste_audio : average audio_vec of liked songs  (how the user likes music to SOUND)
--   dislike_vec : average text_vec of disliked songs (pushes similar songs down the ranking)
ALTER TABLE user_profiles ADD COLUMN IF NOT EXISTS taste_audio vector(8);
ALTER TABLE user_profiles ADD COLUMN IF NOT EXISTS dislike_vec vector(384);

-- Playlist names must not be blank (validation at the database level)
ALTER TABLE playlists DROP CONSTRAINT IF EXISTS playlists_name_not_blank;
ALTER TABLE playlists ADD CONSTRAINT playlists_name_not_blank CHECK (length(btrim(name)) > 0);

-- Default "Liked songs" playlist: flag column + at most ONE per user (partial unique index)
ALTER TABLE playlists ADD COLUMN IF NOT EXISTS is_liked BOOLEAN NOT NULL DEFAULT false;
CREATE UNIQUE INDEX IF NOT EXISTS uq_one_liked_playlist ON playlists (user_id) WHERE is_liked;

-- Third application role 'restricted' (read-only users; mapped to PostgreSQL group role moodtune_restricted in 05_privileges.sql)
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK (role IN ('listener', 'admin', 'restricted'));
